type JobAction = 'REFRESH_CHICAGO' | 'REFRESH_NYC' | 'REFRESH_SBA' | 'REBUILD_DATABASE' | 'VERIFY_DATASET';
type Pipeline = { datasetId: string; manifest: { mode: string; coverageStart: string; coverageEndExclusive: string; importedAt: string } | null; sources: Array<{ source: string; market: string; status: string; completeness: string; retrievedAt: string | null; publisherAsOf: string | null; coverageStart: string | null; coverageEndExclusive: string | null; acceptedRows: number; resolvedRows: number; unresolvedRows: number; missingCostRows: number; checksum: string | null }>; currentJob: Job | null; lastJob: Job | null; serverRestartLimitation: string }; type Job = { id?: string; action?: string; status?: string; stage?: string; outcome?: 'UP_TO_DATE' | 'UPDATED' | null; startedAt?: string; finishedAt?: string; stdout?: string; stderr?: string; note?: string | null };
const jobs: Array<{ action: JobAction; label: string; confirmation?: string }> = [{ action: 'REFRESH_CHICAGO', label: 'Refresh Chicago', confirmation: 'Refresh Chicago from its configured public source? The job stages the result and only replaces the local snapshot after a successful build.' }, { action: 'REFRESH_NYC', label: 'Refresh NYC', confirmation: 'Refresh NYC from its configured public source? The job stages the result and only replaces the local snapshot after a successful build.' }, { action: 'REFRESH_SBA', label: 'Refresh SBA', confirmation: 'Refresh SBA city context from its configured public source? The job stages the result and only replaces the local snapshot after a successful build.' }, { action: 'REBUILD_DATABASE', label: 'Rebuild database', confirmation: 'Rebuild the local database from the bundled staged data? The rebuild is transactional; the previous usable snapshot is retained if it fails.' }, { action: 'VERIFY_DATASET', label: 'Verify dataset' }];
